I noticed this while [fiddling in the repl](http://rollupjs.org/#{%22options%22%3A{%22format%22%3A%22es6%22%2C%22moduleName%22%3A%22myBundle%22%2C%22globals%22%3A{}%2C%22moduleId%22%3A%22%22}%2C%22modules%22%3A[{%22name%22%3A%22main.js%22%2C%22code%22%3A%22import%20{%20counter%2C%20even%20}%20from%20%27.%2Feven%27nn%2F%2F%20console.log%28even%285%29%29nnconsole.log%28counter%29%22}%2C{%22name%22%3A%22even.js%22%2C%22code%22%3A%22import%20{%20odd%20}%20from%20%27.%2Fodd%27nnexport%20var%20counter%20%3D%200%3Bnn%2F%2F%20This%20should%20be%20in%20the%20outputnexport%20const%20foo%20%3D%20odd%2812%29%3Bnnexport%20function%20even%28n%29%20{n%20%20counter%2B%2B%3Bn%20%20alert%28counter%29n%20%20return%20n%20%3D%3D%200%20||%20odd%28n%20-%201%29%3Bn}%22}%2C{%22name%22%3A%22odd.js%22%2C%22code%22%3A%22import%20{%20even%20}%20from%20%27.%2Feven%27%3Bnnexport%20function%20odd%28n%29%20{n%20%20return%20n%20!%3D%200%20%26%26%20even%28n%20-%201%29%3Bn}nnexport%20const%20bar%20%3D%20even%2811%29%3B%22}]})

even.js:

``` js
import { odd } from './odd'

export var counter = 0;

// This should be in the output
export const foo = odd(12);

export function even(n) {
  counter++;
  alert(counter)
  return n == 0 || odd(n - 1);
}
```

odd.js:

``` js
import { even } from './even';

export function odd(n) {
  return n != 0 && even(n - 1);
}

export const bar = even(11);
```

With main.js like so:

``` js
import { counter, even } from './even'

console.log(even(5))

console.log(counter)
```

The output is:

``` js
function odd(n) {
  return n != 0 && even(n - 1);
}

const bar = even(11);

var counter = 0;

function even(n) {
  counter++;
  alert(counter)
  return n == 0 || odd(n - 1);
}

console.log(even(5))

console.log(counter)
```

with `foo` missing. 
If `console.log(even(5))` is commented out, `foo` magically appears!

``` js
function odd(n) {
  return n != 0 && even(n - 1);
}

const bar = even(11);

var counter = 0;

// This should be in the output
const foo = odd(12);

function even(n) {
  counter++;
  alert(counter)
  return n == 0 || odd(n - 1);
}

//console.log(even(5))

console.log(counter)
```
